DELETE
FROM automation_trigger
WHERE name = 'Авто-новая заявка';

INSERT INTO automation_trigger (action, automation_rule_status, description, expression, name, order_number,
                                trigger_type, stop_processing, else_action, workflow_definition, workflow_version)
SELECT rule.action,
       'ENABLED',
       rule.description,
       rule.expression,
       rule.name,
       (SELECT coalesce(max(order_number), -1) FROM automation_trigger) + rule.position,
       rule.trigger_type,
       false,
       null,
       rule.workflow_definition,
       2
FROM (VALUES (1, 'Нужен ответ (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true', NULL,
              '{"version":2,"entryNodeId":"event-mvbaec80-a","nodes":[{"id":"event-mvbaec80-a","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"MESSAGE_INCOMING"}},{"id":"action-mvbaec80-c","type":"ACTION","label":"Действия","x":565.0432632880099,"y":193.13967861557478,"config":{"actionScript":"jev.setAnswerRequiredIfNeeded()","actions":[{"id":"action-item-mvbaec80-e","type":"ASSIGN_LINE","value":null}],"continueOnError":false,"manualScript":true}},{"id":"end-mvbaec80-d","type":"END","label":"Завершение","x":1210.0,"y":220.0,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-mvbaec80-i","source":"action-mvbaec80-c","target":"end-mvbaec80-d","sourceHandle":"next"},{"id":"edge-mvbaehpw-j","source":"event-mvbaec80-a","target":"action-mvbaec80-c","sourceHandle":"next"}]}'),
             (2, 'Умное создание заявки (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true',
              'Заводит заявку по сообщению клиента, если это новый вопрос или повтор проблемы из недавно закрытой заявки. Продолжение открытой заявки, благодарности и автоответы заявку не создают. Заменяет «Авто-новая заявка».',
              '{"version": 2, "entryNodeId": "event-jevassist0", "nodes": [{"id": "event-jevassist0", "type": "EVENT", "label": "Событие", "x": 80.0, "y": 220.0, "config": {"triggerType": "MESSAGE_INCOMING"}}, {"id": "action-jevassist0", "type": "ACTION", "label": "Действия", "x": 565.0, "y": 193.0, "config": {"actionScript": "jev.createTaskIfNeeded()", "actions": [], "continueOnError": false, "manualScript": true}}, {"id": "end-jevassist0", "type": "END", "label": "Завершение", "x": 1210.0, "y": 220.0, "config": {"result": "Сценарий завершён"}}], "edges": [{"id": "edge-jevassist0-a", "source": "event-jevassist0", "target": "action-jevassist0", "sourceHandle": "next"}, {"id": "edge-jevassist0-b", "source": "action-jevassist0", "target": "end-jevassist0", "sourceHandle": "next"}]}'),
             (3, 'Приоритет (Jev)', 'TASK_CREATED', 'workflow.run()', 'true', NULL,
              '{"version":2,"entryNodeId":"event-mvbaqg33-j","nodes":[{"id":"event-mvbaqg33-j","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"TASK_CREATED"}},{"id":"action-mvbaqg33-l","type":"ACTION","label":"Действия","x":476.6378244746601,"y":200.50679851668727,"config":{"actionScript":"jev.setPriority()","actions":[{"id":"action-item-mvbaqg33-n","type":"ASSIGN_LINE","value":null}],"continueOnError":false,"manualScript":true}},{"id":"end-mvbaqg33-m","type":"END","label":"Завершение","x":931.8912237330037,"y":229.2088998763906,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-mvbaqg33-r","source":"action-mvbaqg33-l","target":"end-mvbaqg33-m","sourceHandle":"next"},{"id":"edge-mvbaqt4q-s","source":"event-mvbaqg33-j","target":"action-mvbaqg33-l","sourceHandle":"next"}]}'),
             (4, 'Тип заявки (Jev)', 'TASK_CREATED', 'workflow.run()', 'true', NULL,
              '{"version":2,"entryNodeId":"event-mvbb31gm-1b","nodes":[{"id":"event-mvbb31gm-1b","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"TASK_CREATED"}},{"id":"action-mvbb31gm-1d","type":"ACTION","label":"Действия","x":476.6378244746601,"y":196.82323856613104,"config":{"actionScript":"jev.classifyTask()","actions":[{"id":"action-item-mvbb31gm-1f","type":"ASSIGN_LINE","value":null}],"continueOnError":false,"manualScript":true}},{"id":"end-mvbb31gm-1e","type":"END","label":"Завершение","x":931.8912237330037,"y":231.05067985166872,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-mvbb31gm-1j","source":"action-mvbb31gm-1d","target":"end-mvbb31gm-1e","sourceHandle":"next"},{"id":"edge-mvbb36ua-1k","source":"event-mvbb31gm-1b","target":"action-mvbb31gm-1d","sourceHandle":"next"}]}'),
             (5, 'Детектор массовых инцидентов (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true',
              'Jev размечает входящие сообщения, детектор ищет поток похожих сбоев от разных клиентов. Режим (только логирование или создание черновика инцидента) задаётся в Настройки → Jev.',
              '{"version":2,"entryNodeId":"event-jevinc-a","nodes":[{"id":"event-jevinc-a","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"MESSAGE_INCOMING"}},{"id":"action-jevinc-b","type":"ACTION","label":"Детектор инцидентов","x":565.0,"y":193.0,"config":{"actionScript":"jev.detectIncident()","actions":[],"continueOnError":false,"manualScript":true}},{"id":"end-jevinc-c","type":"END","label":"Завершение","x":1210.0,"y":220.0,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-jevinc-d","source":"event-jevinc-a","target":"action-jevinc-b","sourceHandle":"next"},{"id":"edge-jevinc-e","source":"action-jevinc-b","target":"end-jevinc-c","sourceHandle":"next"}]}'),
             (6, 'Подбор статьи базы знаний (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true',
              'Подбирает к сообщению клиента статью базы знаний и пишет оператору внутренний комментарий с выжимкой от ИИ. Одну статью одному клиенту повторно не предлагает.',
              '{"version": 2, "entryNodeId": "event-jevassist1", "nodes": [{"id": "event-jevassist1", "type": "EVENT", "label": "Событие", "x": 80.0, "y": 220.0, "config": {"triggerType": "MESSAGE_INCOMING"}}, {"id": "action-jevassist1", "type": "ACTION", "label": "Действия", "x": 565.0, "y": 193.0, "config": {"actionScript": "jev.suggestKnowledgeArticle()", "actions": [], "continueOnError": false, "manualScript": true}}, {"id": "end-jevassist1", "type": "END", "label": "Завершение", "x": 1210.0, "y": 220.0, "config": {"result": "Сценарий завершён"}}], "edges": [{"id": "edge-jevassist1-a", "source": "event-jevassist1", "target": "action-jevassist1", "sourceHandle": "next"}, {"id": "edge-jevassist1-b", "source": "action-jevassist1", "target": "end-jevassist1", "sourceHandle": "next"}]}'),
             (7, 'Проверка восстановления после инцидента (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true',
              'Если заявка клиента в инциденте «Наблюдение»/«Восстановлен»: отмечает подтверждение восстановления или уведомляет ответственных, что проблема сохраняется.',
              '{"version": 2, "entryNodeId": "event-jevassist2", "nodes": [{"id": "event-jevassist2", "type": "EVENT", "label": "Событие", "x": 80.0, "y": 220.0, "config": {"triggerType": "MESSAGE_INCOMING"}}, {"id": "action-jevassist2", "type": "ACTION", "label": "Действия", "x": 565.0, "y": 193.0, "config": {"actionScript": "jev.checkIncidentRecovery()", "actions": [], "continueOnError": false, "manualScript": true}}, {"id": "end-jevassist2", "type": "END", "label": "Завершение", "x": 1210.0, "y": 220.0, "config": {"result": "Сценарий завершён"}}], "edges": [{"id": "edge-jevassist2-a", "source": "event-jevassist2", "target": "action-jevassist2", "sourceHandle": "next"}, {"id": "edge-jevassist2-b", "source": "action-jevassist2", "target": "end-jevassist2", "sourceHandle": "next"}]}'),
             (8, 'Эскалация на следующую линию (Jev)', 'MESSAGE_INCOMING', 'workflow.run()', 'true',
              'Переводит открытую заявку клиента на следующую по уровню линию, если текущая не справляется.',
              '{"version": 2, "entryNodeId": "event-jevassist3", "nodes": [{"id": "event-jevassist3", "type": "EVENT", "label": "Событие", "x": 80.0, "y": 220.0, "config": {"triggerType": "MESSAGE_INCOMING"}}, {"id": "action-jevassist3", "type": "ACTION", "label": "Действия", "x": 565.0, "y": 193.0, "config": {"actionScript": "jev.escalateIfNeeded()", "actions": [], "continueOnError": false, "manualScript": true}}, {"id": "end-jevassist3", "type": "END", "label": "Завершение", "x": 1210.0, "y": 220.0, "config": {"result": "Сценарий завершён"}}], "edges": [{"id": "edge-jevassist3-a", "source": "event-jevassist3", "target": "action-jevassist3", "sourceHandle": "next"}, {"id": "edge-jevassist3-b", "source": "action-jevassist3", "target": "end-jevassist3", "sourceHandle": "next"}]}'),
             (9, 'Дубли заявок и инциденты (Jev)', 'TASK_CREATED', 'workflow.run()', 'true',
              'Ищет, не дублирует ли новая заявка открытую: дубль заявки из активного инцидента привязывается к инциденту, о прочих дублях пишет оператору комментарий.',
              '{"version": 2, "entryNodeId": "event-jevassist4", "nodes": [{"id": "event-jevassist4", "type": "EVENT", "label": "Событие", "x": 80.0, "y": 220.0, "config": {"triggerType": "TASK_CREATED"}}, {"id": "action-jevassist4", "type": "ACTION", "label": "Действия", "x": 565.0, "y": 193.0, "config": {"actionScript": "jev.findDuplicate()", "actions": [], "continueOnError": false, "manualScript": true}}, {"id": "end-jevassist4", "type": "END", "label": "Завершение", "x": 1210.0, "y": 220.0, "config": {"result": "Сценарий завершён"}}], "edges": [{"id": "edge-jevassist4-a", "source": "event-jevassist4", "target": "action-jevassist4", "sourceHandle": "next"}, {"id": "edge-jevassist4-b", "source": "action-jevassist4", "target": "end-jevassist4", "sourceHandle": "next"}]}'),
             (10, 'Инцидент по проблеме Zabbix', 'MONITORING_PROBLEM_STARTED', 'workflow.run()', 'true',
              'Проблема мониторинга по сервису (важность от «Высокая») создаёт черновик инцидента или привязывается к активному инциденту сервиса.',
              '{"version":2,"entryNodeId":"event-monprob-a","nodes":[{"id":"event-monprob-a","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"MONITORING_PROBLEM_STARTED"}},{"id":"condition-monprob-d","type":"CONDITION","label":"Важность","x":410.90234857849197,"y":199.08529048207663,"config":{"expression":"problem.severity >= 4","groups":[],"manualExpression":true}},{"id":"action-monprob-b","type":"ACTION","label":"Черновик инцидента","x":793.6341161928307,"y":80.04944375772558,"config":{"actionScript":"incident.fromMonitoring()","actions":[],"continueOnError":false,"manualScript":true}},{"id":"end-monprob-c","type":"END","label":"Завершение","x":1190.0,"y":220.0,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-monprob-e","source":"event-monprob-a","target":"condition-monprob-d","sourceHandle":"next"},{"id":"edge-monprob-f","source":"condition-monprob-d","target":"action-monprob-b","sourceHandle":"true"},{"id":"edge-monprob-g","source":"condition-monprob-d","target":"end-monprob-c","sourceHandle":"false"},{"id":"edge-monprob-h","source":"action-monprob-b","target":"end-monprob-c","sourceHandle":"next"}]}'),
             (11, 'Восстановление по Zabbix', 'MONITORING_PROBLEM_RESOLVED', 'workflow.run()', 'true',
              'Когда все проблемы мониторинга по сервису устранены, объявленный инцидент переводится в «Наблюдение» для проверки восстановления.',
              '{"version":2,"entryNodeId":"event-monres-a","nodes":[{"id":"event-monres-a","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"MONITORING_PROBLEM_RESOLVED"}},{"id":"action-monres-b","type":"ACTION","label":"Проверка восстановления","x":490.18541409147105,"y":199.9752781211372,"config":{"actionScript":"incident.fromMonitoring()","actions":[],"continueOnError":false,"manualScript":true}},{"id":"end-monres-c","type":"END","label":"Завершение","x":984.672435105068,"y":227.26823238566132,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-monres-e","source":"event-monres-a","target":"action-monres-b","sourceHandle":"next"},{"id":"edge-monres-h","source":"action-monres-b","target":"end-monres-c","sourceHandle":"next"}]}'),
             (12, 'Обновления проблем Zabbix в инциденте', 'MONITORING_PROBLEM_UPDATED', 'workflow.run()', 'true',
              'Подтверждения, комментарии и смена важности в Zabbix записываются заметкой в активный инцидент сервиса.',
              '{"version":2,"entryNodeId":"event-monupd-a","nodes":[{"id":"event-monupd-a","type":"EVENT","label":"Событие","x":80.0,"y":220.0,"config":{"triggerType":"MONITORING_PROBLEM_UPDATED"}},{"id":"action-monupd-b","type":"ACTION","label":"Заметка в инцидент","x":461.1124845488257,"y":201.79233621755253,"config":{"actionScript":"incident.fromMonitoring()","actions":[],"continueOnError":false,"manualScript":true}},{"id":"end-monupd-c","type":"END","label":"Завершение","x":922.8924598269468,"y":234.5364647713226,"config":{"result":"Сценарий завершён"}}],"edges":[{"id":"edge-monupd-e","source":"event-monupd-a","target":"action-monupd-b","sourceHandle":"next"},{"id":"edge-monupd-h","source":"action-monupd-b","target":"end-monupd-c","sourceHandle":"next"}]}')) AS rule(position,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             trigger_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             action,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             expression,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             workflow_definition)
WHERE NOT EXISTS (SELECT 1 FROM automation_trigger existing WHERE existing.name = rule.name)
ORDER BY rule.position;
